select count(*)::int as n from (values ('public', 'set_session_price'), ('public', 'record_appointment_settlement'), ('public', 'edit_client_pinned_note'), ('public', 'audit_pinned_note_delete'), ('public', 'audit_client_pricing_change')) v(s, f) where exists (select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = v.s and p.proname = v.f)